 function logText(row){const n=esc(row.name),target=esc(row.target);return ({'battle-effect':t(n+' · '+esc(row.cause)+(row.healed?' +'+row.healed:' −'+(row.damage||0))+' HP',n+' · '+esc(row.cause)+(row.healed?' +'+row.healed:' −'+(row.damage||0))+' HP'),weather:t('อากาศ · '+(WEATHER[row.weather]?.[0]||row.weather),'Weather · '+(WEATHER[row.weather]?.[1]||row.weather)),ability:t(n+' · Ability '+esc(row.ability),n+' · Ability '+esc(row.ability)),equipped:t(n+' ถือ '+esc(row.item),n+' is holding '+esc(row.item)),unequipped:t('นำ '+esc(row.item)+' กลับกระเป๋า','Returned '+esc(row.item)+' to the bag'),'received-item':t('ได้รับ '+n+' ×'+row.quantity,'Received '+n+' ×'+row.quantity),'used-item':t('ใช้ '+n+' กับ '+target,'Used '+n+' on '+target),learned:t(n+' เรียน '+esc(row.move),n+' learned '+esc(row.move)),'cheat-spawn':t('Sandbox · เพิ่ม '+n,'Sandbox · created '+n),'cheat-item':t('Sandbox · '+n+' ×'+row.quantity,'Sandbox · '+n+' ×'+row.quantity),'cheat-edit':t('Sandbox · แก้ไข '+n,'Sandbox · edited '+n),'cheat-heal':t('Sandbox · ฟื้นฟูทุกตัว','Sandbox · healed all'),residual:t(n+' ได้รับผล '+esc(row.status)+' −'+row.damage+' HP',n+' suffers '+esc(row.status)+' −'+row.damage+' HP'),'send-out':t(n+' ออกมาอยู่ด้วย',n+' is out with you'),'recall':t('เรียก '+n+' กลับเข้าบอล',n+' returned to its ball'),'trainer-offered':t(n+' ท้าประลอง',n+' offered a battle'),'trainer-start':t('เริ่มท้าสู้ '+n,'Challenged '+n),'trainer-next':t('คู่แข่งส่ง '+n+' · +'+row.xp+' EXP','Opponent sent '+n+' · +'+row.xp+' EXP'),'trainer-victory':t('ชนะ '+n+(row.badge?' · ได้ Badge':''),'Defeated '+n+(row.badge?' · Badge earned':'')),'quest-offered':t('ภารกิจตามหา '+n,'Quest offered: '+n),'quest-accepted':t('รับภารกิจ '+n,'Quest accepted: '+n),starter:t('ได้ '+n+' เป็นคู่หู',n+' joined your party'),encounter:t('พบ '+n+' ป่า · Lv. '+row.level,'Wild '+n+' appeared · Lv. '+row.level),'player-hit':t(n+' ใช้ '+esc(row.move),n+' used '+esc(row.move))+(row.miss?t(' · พลาด',' · Missed'):' · −'+row.damage+' HP')+(row.effect>1?t(' · ได้ผลดีมาก',' · Super effective'):row.effect===0?t(' · ไม่มีผล',' · No effect'):''),'enemy-hit':t(n+' ใช้ '+esc(row.move),n+' used '+esc(row.move))+(row.miss?t(' · พลาด',' · Missed'):' · '+target+' −'+row.damage+' HP'),victory:t('ชนะการต่อสู้ · +'+row.xp+' EXP','Battle won · +'+row.xp+' EXP')+(row.leveled?' · Lv. '+row.level:''),caught:t('จับ '+n+' สำเร็จ',n+' was caught')+(row.storage==='box'?t(' · ส่งเข้ากล่อง',' · Sent to storage'):''),'escaped-ball':t(n+' หลุดจากบอล',n+' broke free'),run:t('ออกจากการเผชิญหน้า','Left the encounter'),heal:t('ฟื้นฟู HP และ PP แล้ว','HP and PP restored'),potion:t('ใช้ Potion กับ '+n,'Used Potion on '+n),switch:t('เปลี่ยนเป็น '+n,'Switched to '+n),fainted:t(n+' หมดสภาพ',n+' fainted'),defeat:t('ทีมหมดสภาพ · กลับไปฟื้นฟูก่อน','Your team fainted. Visit the Pokémon Center.'),lead:t(n+' นำทีม',n+' is your lead companion'),deposit:t('ฝาก '+n+' เข้ากล่อง',n+' moved to storage'),withdraw:t('นำ '+n+' เข้าทีม',n+' joined the party'),evolved:t(esc(row.from)+' พัฒนาเป็น '+n,esc(row.from)+' evolved into '+n)})[row.key]||'';}
 function recent(count=5){return game.logs.length?`<ol class="pk-log">${game.logs.slice(-count).reverse().map(row=>`<li>${fa(['caught','victory','evolved'].includes(row.key)?'star':'angle-right')}<span>${logText(row)}</span></li>`).join('')}</ol>`:'';}
 function adventure(){if(!game.started)return starter();if(game.battle||visualBattle)return battle();const m=game.pokemon[game.party[0]],p=dex.get(m.key);return `${sectionHead(t('การเดินทาง / ','JOURNEY / ')+game.region,t('พร้อมออกเดินทาง','A world to discover'),'')}<div class="pk-journey-hero"><div class="pk-hero-copy"><span class="pk-eyebrow">${t('คู่หูของคุณ','YOUR COMPANION')}</span><h2>${esc(monName(m))}</h2><p>Lv. ${m.level} <span>·</span> ${p.types.map(typeBadge).join(' ')}</p>${hp(m)}${expBar(m)}<div class="pk-hero-actions">${button(fa('compass')+' '+t('สำรวจเส้นทาง','Explore the route'),'explore','','pk-primary')}${button(t('ดูคู่หู','View partner')+' '+fa('arrow-right'),'mon-detail','data-uid="'+m.uid+'"','pk-link')}</div></div><div class="pk-hero-art">${image(p,m)}</div></div><div class="pk-trainer-metrics"><div><strong>${game.caught.length}</strong><span>${t('สายพันธุ์ที่จับได้','SPECIES CAUGHT')}</span></div><div><strong>${game.wins}</strong><span>${t('การต่อสู้ที่ชนะ','BATTLES WON')}</span></div><div><strong>${game.party.length}<small> / 6</small></strong><span>${t('เพื่อนร่วมทาง','PARTY MEMBERS')}</span></div></div><div class="pk-subhead"><h2>${t('บันทึกการเดินทาง','Field journal')}</h2>${button(t('ทั้งหมด','View all')+' '+fa('arrow-right'),'nav','data-view="journal"','pk-link')}</div>${recent(4)}<div class="pk-service-entry">${button(fa('briefcase-medical')+' '+t('บริการและการฝึก','Services & training'),'nav','data-view="services"','pk-primary')}</div><div class="pk-footer-actions">${button(fa('heart')+' '+t('ศูนย์โปเกมอน','Pokémon Center'),'nav','data-view="center"','','pk-quiet')}${button(fa('feather-pointed')+' '+t('บรรยายต่อในแชท','Continue the story'),'narrate',''+(!pendingNarration||working?' disabled':''),'pk-quiet')}</div>`;}
 function movesMarkup(m){const fallback=!m.moves.some(v=>v.pp>0&&supportedMove(dex,v.id)&&moveAllowed(m,dex.moves[v.id]))?button('Struggle','attack','data-move="165"','pk-move'):'';return fallback+m.moves.map(slot=>{const move=dex.moves[slot.id],factor=game.battle&&move.power?effectiveness(dex,move.type,dex.get(game.battle.wild.key).types):1;return button(`<span><strong>${esc(move.name)}</strong><small>${typeBadge(move.type)}${factor>1?'<em>'+t('ได้ผลดี','Effective')+'</em>':factor===0?'<em>'+t('ไม่มีผล','No effect')+'</em>':''}</small></span><span class="pk-move-pp">${slot.pp}<small> / ${move.pp} PP</small></span>`,'attack','data-move="'+slot.id+'" style="--pk-move-color:'+typeColors[move.type]+'"'+(slot.pp<=0||working||!supportedMove(dex,slot.id)||!moveAllowed(m,move)?' disabled':''),'pk-move');}).join('');}
 function battle(){const field=resolveTerrain(game.settings.terrain,context().state?.location),b=game.battle||visualBattle,m=game.pokemon[b.activeUid],foe=b.wild,p=dex.get(foe.key),partyBalls=game.party.map(uid=>`<span class="pk-ball tiny ${game.pokemon[uid].hp?'':'fainted'}"></span>`).join('');return `<div class="pk-battle-heading"><span class="pk-location">${fa('location-dot')} ${esc(game.region)} · ${esc(t(field.th,field.en))}${b.trainer?' · '+esc(b.trainer.name):''}${b.weather&&b.weather!=='clear'?' · '+esc(t(...WEATHER[b.weather])):''}</span><span>${t('เทิร์น','TURN')} ${b.round}</span></div><div class="pk-arena" data-terrain="${field.id}" style="--pk-terrain:url('${new URL('assets/battle/layers/'+field.id+'-background.png',import.meta.url)}')"><div class="pk-background-layer" aria-hidden="true"></div><div class="pk-arena-clouds" aria-hidden="true"></div><div class="pk-battle-status pk-foe-status"><div><h2>${esc(p.name)} <span class="pk-wild-tag">${b.trainer?'TRAINER':t('ป่า','WILD')}</span></h2><small>Lv. ${foe.level} ${foe.traits?.gender==='female'?'♀':foe.traits?.gender==='male'?'♂':''}</small></div>${hp(foe)}${b.trainer?'<div class="pk-party-balls pk-opponent-balls" aria-label="'+esc(b.trainer.name)+' · '+b.trainer.team.length+' Pokémon">'+b.trainer.team.map((mon,i)=>'<span class="pk-ball tiny '+(mon.hp?'':'fainted')+(i===b.trainer.index?' is-active':'')+'"></span>').join('')+'</div>':''}</div><div class="pk-platform pk-platform-foe"><img class="pk-platform-art" src="${new URL('assets/battle/layers/'+field.id+'-foe.png?v=layer3',import.meta.url)}" alt="" aria-hidden="true"><div class="pk-foe-art">${battleImage(p,foe,'front')}</div></div><div class="pk-platform pk-platform-ally"><img class="pk-platform-art" src="${new URL('assets/battle/layers/'+field.id+'-ally.png?v=layer3',import.meta.url)}" alt="" aria-hidden="true"><div class="pk-ally-art">${battleImage(dex.get(m.key),m,'back')}</div></div><div class="pk-battle-status pk-ally-status"><div><h2>${esc(monName(m))}</h2><small>Lv. ${m.level} ${m.traits?.gender==='female'?'♀':m.traits?.gender==='male'?'♂':''}</small></div>${hp(m)}${expBar(m)}<div class="pk-party-balls" aria-label="${game.party.length} Pokémon">${partyBalls}</div></div></div><div class="pk-battle-console"><div class="pk-battle-message"><span class="pk-game-caret" aria-hidden="true"></span><p>${game.lastResult?.key==='encounter'?esc(p.name)+' '+t('ป่าปรากฏตัว!','appeared!'):game.logs.slice(-2).map(logText).filter(Boolean).join('<br>')}</p></div>${battlePane==='party'?`<div class="pk-command-pane">${button(fa('arrow-left')+' '+t('คำสั่ง','Commands'),'battle-menu','data-pane="commands"','pk-link')}<div class="pk-battle-party">${game.party.map(uid=>{const ally=game.pokemon[uid];return button(image(dex.get(ally.key),ally)+'<span><strong>'+esc(monName(ally))+'</strong><small>Lv. '+ally.level+' · HP '+ally.hp+'/'+ally.stats[0]+'</small></span>', 'switch','data-uid="'+esc(uid)+'"'+(b.activeUid===uid||!ally.hp||!game.battle?' disabled':''),'pk-battle-party-member');}).join('')}</div></div>`:battlePane==='moves'?`<div class="pk-command-pane">${button(fa('arrow-left')+' '+t('คำสั่ง','Commands'),'battle-menu','data-pane="commands"','pk-link')}<div class="pk-moves">${movesMarkup(m)}</div></div>`:battlePane==='bag'?`<div class="pk-command-pane">${button(fa('arrow-left')+' '+t('คำสั่ง','Commands'),'battle-menu','data-pane="commands"','pk-link')}<div class="pk-battle-tools">${Object.entries(game.inventory).filter(([id,n])=>n>0&&['ball','medicine'].includes(itemEffect(id).kind)).map(([id,n])=>button(itemSprite(id)+'<span>'+esc(itemName(dex,id))+'<small>× '+n+'</small></span>',itemEffect(id).kind==='ball'?'catch':'choose-medicine','data-'+(itemEffect(id).kind==='ball'?'ball':'item')+'="'+id+'"'+(b.trainer&&itemEffect(id).kind==='ball'?' disabled':''),'pk-item-command')).join('')}</div></div>`:`<div class="pk-command-grid">${button(fa('burst')+'<span>'+t('ต่อสู้','FIGHT')+'</span>','battle-menu','data-pane="moves"','pk-command fight')}${button(fa('bag-shopping')+'<span>'+t('กระเป๋า','BAG')+'</span>','battle-menu','data-pane="bag"','pk-command bag')}${button(partyIcon+'<span>'+t('โปเกมอน','POKÉMON')+'</span>','battle-menu','data-pane="party"','pk-command party')}${button(fa('person-running')+'<span>'+t(b.trainer?'ยอมแพ้':'หนี',b.trainer?'FORFEIT':'RUN')+'</span>',b.trainer?'forfeit':'run','','pk-command run')}</div>`}</div><div class="pk-battle-footer">${button(fa('feather-pointed')+' '+t('บรรยายต่อ','Continue story'),'narrate',!pendingNarration||working?'disabled':'','pk-link')}${button(fa('clock-rotate-left')+' '+t('บันทึก','Battle log'),'nav','data-view="journal"','pk-link')}</div>`;}
 function monCard(uid,storage=false){const m=game.pokemon[uid],p=dex.get(m.key),lead=game.party[0]===uid;return `<article class="pk-mon-card ${lead&&!storage?'is-lead':''}"><button type="button" class="pk-mon-open" data-pk-action="mon-detail" data-uid="${esc(uid)}"><div class="pk-mon-art">${image(p,m)}</div><div><span class="pk-number">${lead&&!storage?t('คู่หูนำทีม','LEAD PARTNER'):'#'+String(p.speciesId).padStart(4,'0')}</span><h2>${esc(monName(m))}</h2><p>Lv. ${m.level} · ${p.types.map(typeBadge).join(' ')}</p>${hp(m)}</div></button><div class="pk-card-actions">${game.battle&&!storage?button(t(game.battle.activeUid===uid?'กำลังต่อสู้':'ส่งลงต่อสู้',game.battle.activeUid===uid?'Active':'Switch in'),'switch','data-uid="'+uid+'"'+(game.battle.activeUid===uid||!m.hp?' disabled':''),'pk-primary'):button(fa(storage?'arrow-up-from-bracket':'box-archive')+' '+(storage?t('เข้าทีม','To party'):t('เข้ากล่อง','Store')),storage?'withdraw':'deposit','data-uid="'+uid+'"'+(!storage&&game.party.length<=1||storage&&game.party.length>=6||game.battle?' disabled':''),'pk-link')}${!storage&&!game.battle?button(game.outUid===uid?t('เรียกกลับ','Recall'):t('ปล่อยออกมา','Send out'),game.outUid===uid?'recall':'send-out','data-uid="'+uid+'"'+(!m.hp?' disabled':''),'pk-link'):''}${!storage&&!game.battle&&!lead?button(fa('flag')+' '+t('นำทีม','Lead'),'lead','data-uid="'+uid+'"'+(!m.hp?' disabled':''),'pk-link'):''}${evolutionOptions(game,dex,uid).some(e=>e.ready)?button(fa('wand-magic-sparkles')+' '+t('พัฒนา','Evolve'),'mon-detail','data-uid="'+uid+'"','pk-link'):''}</div></article>`;}
 function team(){return sectionHead('YOUR COMPANIONS',t('ทีมเดินทาง','Your party'),'<span class="pk-counter">'+game.party.length+' / 6</span>')+(game.battle?`<div class="pk-footer-actions">${battleButton()}</div>`:'')+(game.party.length?`<div class="pk-party-grid">${game.party.map(uid=>monCard(uid)).join('')}</div><div class="pk-footer-actions">${button(fa('heart')+' '+t('ฟื้นฟูทั้งทีม','Heal party'),'nav','data-view="center"','pk-quiet')}</div>`:empty(t('ยังไม่มีคู่หู','No partner yet'),t('เริ่มการเดินทางแล้วเลือกคู่หู','Choose a partner in Journey.')));}
 function storage(){return sectionHead('POKÉMON STORAGE',t('กล่องโปเกมอน','Pokémon storage'),'<span class="pk-counter">'+game.box.length+'</span>')+(game.box.length?`<div class="pk-party-grid">${game.box.map(uid=>monCard(uid,true)).join('')}</div>`:empty(t('พื้นที่สำหรับเพื่อนใหม่','Room for new companions'),t('เมื่อทีมครบ 6 ตัว โปเกมอนที่จับเพิ่มจะมาอยู่ที่นี่','New catches arrive here when your party is full.'),'boxes-stacked'));}
 function dexView(){const needle=query.trim().toLowerCase(),aliases={'การ์เดอวัวร์':'gardevoir','การ์ดิวัวร์':'gardevoir','ราลท์ซ':'ralts','พิคาชู':'pikachu','ปิกาจู':'pikachu','อีวุย':'eevee','ฟุชิกิดาเนะ':'bulbasaur','ฮิโตคาเงะ':'charmander','เซนิกาเมะ':'squirtle'},search=aliases[needle]||needle,numeric=/^#?[0-9]+$/u.test(search)?Number(search.replace('#','')):null,all=dex.forms.filter(p=>(showForms||p.default)&&(!type||p.types.includes(type))&&(!generation||p.generation===generation)&&(!search||(numeric!==null?p.speciesId===numeric:[p.name,p.form,p.key].some(v=>String(v).toLowerCase().includes(search))))),page=all.slice(dexPage*24,dexPage*24+24);return `${sectionHead('POKÉDEX',t('ค้นพบโปเกมอน','Discover Pokémon'),'<span class="pk-counter">'+dex.source.species+' <small>'+t('สายพันธุ์','species')+'</small></span>')}<div class="pk-search"><label>${fa('magnifying-glass')}<input data-pk-search type="search" value="${esc(query)}" placeholder="${t('ชื่อ หรือหมายเลข #0025','Name or number #0025')}" aria-label="${t('ค้นหา Pokédex','Search Pokédex')}"></label>${button(fa('filter'),'dex-filters','aria-expanded="'+dexFilters+'" aria-label="'+t('ตัวกรอง','Filters')+'"','pk-icon')}</div><div class="pk-dex-mode">${button(t('สายพันธุ์','Species'),'dex-mode','data-forms="false" aria-pressed="'+(!showForms)+'"')}${button(t('รวมทุกฟอร์ม','Include forms'),'dex-mode','data-forms="true" aria-pressed="'+showForms+'"')}<span>${all.length.toLocaleString()} ${t('รายการ','entries')}</span></div>${dexFilters?`<section class="pk-filter-panel"><strong>${t('ธาตุ','TYPE')}</strong><div class="pk-type-filters">${button(t('ทั้งหมด','All'),'filter-type','data-type="" aria-pressed="'+(!type)+'"')}${dex.types.map(v=>button(typeBadge(v),'filter-type','data-type="'+v+'" aria-pressed="'+(type===v)+'"')).join('')}</div><strong>${t('เจเนอเรชัน','GENERATION')}</strong><div class="pk-gen-filters">${button(t('ทั้งหมด','All'),'filter-generation','data-generation="0" aria-pressed="'+(!generation)+'"')}${REGIONS.map((r,i)=>button(String(i+1),'filter-generation','data-generation="'+(i+1)+'" aria-label="Generation '+(i+1)+' '+r+'" aria-pressed="'+(generation===i+1)+'"')).join('')}</div></section>`:''}<div class="pk-subhead"><span>${t('พบแล้ว','Seen')} ${game.seen.length} · ${t('จับแล้ว','Caught')} ${game.caught.length}</span>${type||generation?button(t('ล้างตัวกรอง','Clear filters'),'clear-filters','','pk-link'):''}</div><div class="pk-dex-grid">${page.map(p=>`<button class="pk-dex-card" data-pk-action="dex-detail" data-key="${esc(p.key)}" style="--pk-card-type:${typeColors[p.types[0]]}"><div class="pk-dex-card-top"><span class="pk-number">#${String(p.speciesId).padStart(4,'0')}</span>${game.caught.includes(p.speciesId)?'<span class="pk-ball tiny" aria-label="Caught"></span>':''}</div><div class="pk-dex-art">${image(p)}</div><h2>${esc(p.name)}</h2>${p.form?'<small class="pk-form-name">'+esc(p.form)+'</small>':''}<div class="pk-types">${p.types.map(typeBadge).join('')}</div></button>`).join('')}</div>${!page.length?empty(t('ไม่พบโปเกมอน','No Pokémon found'),t('ลองใช้ชื่อภาษาอังกฤษหรือหมายเลข','Try an English name or number.'),'magnifying-glass'):''}<div class="pk-pagination">${button(fa('arrow-left'),'dex-page','data-page="'+(dexPage-1)+'"'+(!dexPage?' disabled':''),'pk-icon')}<span>${dexPage+1} / ${Math.max(1,Math.ceil(all.length/24))}</span>${button(fa('arrow-right'),'dex-page','data-page="'+(dexPage+1)+'"'+((dexPage+1)*24>=all.length?' disabled':''),'pk-icon')}</div>`;}
 function condition(e){if(e.trigger===2)return t('แลกแล้วรับคืนที่ Center / Link Club'+(e.held?' · '+title(e.held):''),'Trade-back at Center / Link Club'+(e.held?' · '+title(e.held):''));if(e.reason==='special'||e.reason==='affection')return t('เงื่อนไขพิเศษ · ดูใน Pokédex','Special requirements · Pokédex reference');return [e.level?'Lv. '+e.level:'',e.item?title(e.item):'',e.friendship?t('มิตรภาพ','Friendship')+' '+e.friendship:'',e.time||''].filter(Boolean).join(' · ')||t('เงื่อนไขพิเศษ','Special condition');}
 function detail(){const p=dex.get(selected)||dex.get(282),m=selectedUid?game.pokemon[selectedUid]:null,forms=dex.forms.filter(v=>v.speciesId===p.speciesId),options=m?evolutionOptions(game,dex,m.uid,{place:context().state?.location?.place,time:context().state?.worldClock?.time}):p.evolutions.map(e=>({...e,target:dex.bySpecies.get(e.to),ready:false,reason:e.trigger===2?'trade':''}));return `${button(fa('arrow-left')+' '+t('กลับ','Back'),'nav','data-view="'+previousView+'"','pk-link')}<div class="pk-detail-hero"><div class="pk-detail-art">${image(p,m)}<span class="pk-detail-number">${String(p.speciesId).padStart(4,'0')}</span></div><div class="pk-detail-copy"><span class="pk-eyebrow">${esc(p.genus)} · GEN ${p.generation}</span><h1>${esc(m?monName(m):p.name)}</h1>${p.form?'<p class="pk-form-title">'+esc(p.form)+'</p>':''}<div class="pk-types">${p.types.map(typeBadge).join('')}</div><div class="pk-detail-metrics"><div><strong>${p.height}<small> m</small></strong><span>${t('ส่วนสูง','HEIGHT')}</span></div><div><strong>${p.weight}<small> kg</small></strong><span>${t('น้ำหนัก','WEIGHT')}</span></div></div><p class="pk-abilities">${p.abilities.map(a=>esc(title(a.name))+(a.hidden?' <small>H</small>':'')).join(' / ')}</p>${m?`<div class="pk-detail-actions">${button(t('ฝึกและจัดท่า','Train & manage moves'),'open-training','data-uid="'+m.uid+'"','pk-primary')}${nicknameEditing?`<form class="pk-nickname-form" data-pk-nickname><label>${t('ชื่อเล่น','Nickname')}<input name="nickname" maxlength="36" value="${esc(m.nickname)}" placeholder="${esc(p.name)}"></label><button type="submit" class="pk-primary" aria-label="${t('บันทึก','Save')}">${fa('check')}</button>${button(fa('xmark'),'edit-nickname','aria-label="Cancel"','pk-icon')}</form>`:button(fa('pen')+' '+t('ตั้งชื่อเล่น','Nickname'),'edit-nickname','','pk-link')}</div><div class="pk-owned"><span>Lv. ${m.level}</span>${hp(m)}${expBar(m)}<p>EXP ${m.exp.toLocaleString()} / ${experienceFor(dex,p,Math.min(100,m.level+1)).toLocaleString()}</p></div>`:`<span class="pk-dex-status">${game.caught.includes(p.speciesId)?t('ลงทะเบียนที่จับได้แล้ว','Registered as caught'):game.seen.includes(p.speciesId)?t('เคยพบแล้ว','Seen in your journey'):t('ข้อมูลอ้างอิง · ยังไม่เคยพบ','Reference · not yet encountered')}</span>`}</div></div>${m?expansion.specimen(m):''}<div class="pk-detail-lower"><section><div class="pk-subhead"><h2>${t('ค่าสถานะพื้นฐาน','Base stats')}</h2></div><div class="pk-stat-bars">${['HP','Attack','Defense','Sp. Atk','Sp. Def','Speed'].map((v,i)=>`<div><span>${v}</span><b>${p.stats[i]}</b><span class="pk-track"><i style="width:${Math.min(100,p.stats[i]/255*100)}%"></i></span></div>`).join('')}</div></section><section><div class="pk-subhead"><h2>${t('เส้นทางวิวัฒนาการ','Evolution')}</h2></div>${p.prevo?button(dex.get(p.prevo)?.name+' '+fa('arrow-right')+' '+p.name,'dex-detail','data-key="'+dex.get(p.prevo)?.key+'"','pk-evolution'):''}${options.length?options.map(e=>`<div class="pk-evolution"><div><strong>${esc(e.target?.name||e.to)}</strong><small>${esc(condition(e))}</small></div>${m?button(e.ready?t('พัฒนา','Evolve'):e.reason==='trade'?t('แลกแล้วรับคืน','Trade & return'):t('ยังไม่พร้อม','Not ready'),e.reason==='trade'?'trade-evolve':'evolve','data-uid="'+m.uid+'" data-to="'+e.to+'"'+(!e.ready&&e.reason!=='trade'||game.battle?' disabled':''),'pk-primary'):button(fa('arrow-right'),'dex-detail','data-key="'+e.target?.key+'" aria-label="'+esc(e.target?.name)+'"','pk-icon')}</div>`).join(''):'<p class="pk-muted">'+t('ไม่มีขั้นถัดไป','No further evolution')+'</p>'}</section></div>${forms.length>1?`<section class="pk-forms"><div class="pk-subhead"><h2>${t('ฟอร์มต่าง ๆ','Forms')}</h2><span>${forms.length}</span></div><div class="pk-form-grid">${forms.map(f=>button(`<div>${image(f)}</div><span>${esc(f.form||t('ฟอร์มปกติ','Standard'))}</span>`,'dex-detail','data-key="'+f.key+'" aria-pressed="'+(f.key===p.key)+'"','pk-form')).join('')}</div><p class="pk-muted">${t('ฟอร์มใน Pokédex เป็นข้อมูลอ้างอิง การเปลี่ยนร่างระหว่างต่อสู้ยังไม่จำลอง','Form browsing is reference. Battle transformations are not simulated.')}</p></section>`:''}`;}
 function medicineForm(){const effect=itemEffect(medicine),m=game.pokemon[medicineTarget]||game.pokemon[game.battle?.activeUid||game.party[0]];if(!m)return'';return `${button(fa('arrow-left')+' '+t('กลับ','Back'),'nav','data-view="'+(game.battle?'adventure':'bag')+'"','pk-link')}<section class="pk-medicine-card"><div>${itemSprite(medicine)}<h1>${esc(itemName(dex,medicine))}</h1><span>×${game.inventory[medicine]||0}</span></div><form data-pk-use-item><label>${t('ใช้กับตัวไหน','Choose a Pokémon')}<select name="uid" data-pk-medicine-target>${game.party.map(id=>`<option value="${id}"${m.uid===id?' selected':''}>${esc(monName(game.pokemon[id]))} · ${game.pokemon[id].hp}/${game.pokemon[id].stats[0]} HP</option>`).join('')}</select></label>${effect.pp&&!effect.allPP?`<label>${t('ฟื้น PP ของท่า','Move to restore')}<select name="moveId">${m.moves.map(v=>`<option value="${v.id}">${esc(dex.moves[v.id].name)} · ${v.pp}/${dex.moves[v.id].pp} PP</option>`).join('')}</select></label>`:''}<p>${t('ไอเทมจะถูกหักเมื่อใช้สำเร็จเท่านั้น','An item is consumed only when it has an effect.')}${game.battle?' · '+t('คู่แข่งจะได้ตอบโต้','The opponent gets a turn.'):''}</p><button class="pk-primary" type="submit">${t('ใช้ไอเทม','Use item')}</button></form></section>`;}
 function bag(){const all=bagCatalogue?[...dex.items.values()].map(i=>({...i,quantity:game.inventory[i.id]||0})):Object.entries(game.inventory).filter(([,n])=>n>0).map(([id,quantity])=>({id,name:itemName(dex,id),quantity})),filtered=all.filter(i=>[i.name,i.id].join(' ').toLowerCase().includes(bagSearch.toLowerCase())),max=Math.max(1,Math.ceil(filtered.length/24));bagPage=Math.min(bagPage,max-1);return `${sectionHead('BAG',t('กระเป๋าสำหรับทุกการเดินทาง','Ready for every journey'))}<div class="pk-bag-toolbar"><input data-pk-bag-search value="${esc(bagSearch)}" placeholder="${t('ค้นหาไอเทม…','Search items…')}" aria-label="${t('ค้นหาไอเทม','Search items')}">${button(bagCatalogue?t('ดูของที่มี','Owned items'):t('ทะเบียนทั้งหมด','Full catalogue'),'bag-catalogue','','pk-quiet')}${button(t('คลังร่วม RoleForge','RoleForge bridge'),'nav','data-view="bridge"','pk-quiet')}</div><p class="pk-muted">${filtered.length} ${t('รายการ · แยกเอฟเฟกต์ที่รองรับกับข้อมูลอ้างอิง','items · implemented effects are distinguished from reference-only data')}</p><div class="pk-bag-grid">${filtered.slice(bagPage*24,bagPage*24+24).map(i=>{const effect=itemEffect(i.id);return `<article><div class="pk-item-icon">${itemSprite(i.id)}</div><div><h2>${esc(i.name)}</h2><p>${effect.kind==='reference'?t('ข้อมูลอ้างอิง · ยังไม่มีเอฟเฟกต์','Reference only · effect not implemented'):effect.kind==='ball'?t('ใช้จับตัวป่าใน Battle Bag','Catch wild Pokémon from the battle Bag'):effect.kind==='medicine'?t('ยา / ฟื้นฟู · เลือกตัวก่อนใช้','Medicine / recovery · choose a recipient'):effect.kind==='held'?t('ให้ถือได้จากหน้า Ability และไอเทมถือ','Equip through Abilities & held items'):effect.kind==='machine'?t('ใช้ผ่านหน้าฝึกท่าที่เข้ากันได้','Use through compatible move training'):t('ใช้ผ่านหน้าวิวัฒนาการ','Use through a compatible evolution')}</p></div><strong>× ${i.quantity}</strong>${effect.kind==='held'&&i.quantity?button(t('ให้ถือ','Equip'),'nav','data-view="equipment"','pk-primary'):''}${effect.kind==='medicine'&&i.quantity?button(t('เลือกใช้','Use'),'choose-medicine','data-item="'+i.id+'"','pk-primary'):''}</article>`;}).join('')}</div><div class="pk-pagination">${button('‹','bag-page','data-step="-1"'+(!bagPage?' disabled':''),'pk-icon')}<span>${bagPage+1} / ${max}</span>${button('›','bag-page','data-step="1"'+(bagPage+1>=max?' disabled':''),'pk-icon')}</div>${medicine?medicineForm():''}`;}

