 const expansion=createExpansionPanels({get:()=>({game,dex,t,button,sectionHead,image,hp,root,place:context().state?.location?.place||'',roleInventory:context().state?.inventory||[],resolveRoleItem:i=>resolveRoleItem(dex,i)}),apply,navigate:next=>{view=next;render();root.querySelector('.pk-main').scrollTop=0;},render,importItem:input=>apply(input)});
 const release=releasePanels({get:()=>({game,dex,t,button,sectionHead,showError}),apply,render});
 const content=()=>release.render(view)??expansion.render(view)??(({adventure,team,dex:dexView,storage,bag,'battle-medicine':medicineForm,settings,detail,journal:()=>sectionHead('FIELD JOURNAL',t('บันทึกการเดินทาง','Field journal'))+recent(40)})[view]?.()||adventure());
 function viewport(){root.style.setProperty('--pk-vh',(visualViewport?.height||innerHeight)+'px');root.style.setProperty('--pk-vtop',(visualViewport?.offsetTop||0)+'px');}
 function apertureMarkup(pageContent){return `<div class="pk-shell pk-aperture"><header class="pk-aperture-header"><div class="pk-aperture-brand"><span class="pk-brand-emblem" role="img" aria-label="Pokémon">${partyIcon}</span></div><div class="pk-aperture-meta"><span>${esc(game.region)}</span><b>${game.caught.length}<small> ${t('จับแล้ว','CAUGHT')}</small></b></div><div class="pk-aperture-window">${button(fa('window-minimize'),'dock','aria-label="'+t('ย่อ','Minimize')+'"','pk-icon')}${button(fa('xmark'),'close','aria-label="'+t('ปิด','Close')+'"','pk-icon')}</div></header><div class="pk-layout"><nav class="pk-nav" aria-label="Pokémon">${tabs.map(([id,icon,th,en],i)=>button('<span class="pk-aperture-nav-index">0'+(i+1)+'</span>'+(id==='team'?partyIcon:fa(icon))+'<span>'+t(th,en)+'</span>','nav','data-view="'+id+'" aria-current="'+(view===id?'page':'false')+'"')).join('')}<div class="pk-aperture-nav-foot"><span class="pk-aperture-orbit" aria-hidden="true"></span><small>FIELD<br>COMPANION</small></div></nav><main class="pk-main">${notice?'<div class="pk-notice" role="status">'+esc(notice)+'</div>':''}${pageContent}</main></div></div>`;}
 function composeBattleLayout(){const main=root.querySelector('.pk-main'),arena=main?.querySelector('.pk-arena');if(!arena)return;const layout=document.createElement('section');layout.className='pk-encounter-layout';const field=document.createElement('div');field.className='pk-encounter-field';const control=document.createElement('aside');control.className='pk-encounter-control';const heading=main.querySelector('.pk-battle-heading'),console=main.querySelector('.pk-battle-console'),footer=main.querySelector('.pk-battle-footer');main.insertBefore(layout,heading||arena);layout.append(field,control);if(heading)field.append(heading);field.append(arena);control.innerHTML='<div class="pk-control-caption"><span>'+t('แผนการต่อสู้','BATTLE CONTROL')+'</span><strong>'+t('ตาคุณแล้ว','Your next move')+'</strong></div>';if(console)control.append(console);if(footer)control.append(footer);const roster=document.createElement('div');roster.className='pk-field-roster';roster.innerHTML='<span>'+t('ทีมของคุณ','YOUR PARTY')+'</span>'+game.party.map(uid=>{const mon=game.pokemon[uid];return '<div>'+image(dex.get(mon.key),mon)+'<span>'+esc(monName(mon))+'<small>Lv. '+mon.level+'</small></span></div>';}).join('');field.append(roster);}
 function render(){if(disposed||!game)return;const main=root.querySelector('.pk-main'),scroll=main?.scrollTop||0;root.lang=uiLanguage();root.dataset.pkView=view;root.dataset.pkFieldMotion=game.settings.motion===false?'off':'on';root.dataset.pkTheme=game.settings.theme||'original';panel.dataset.pkTheme=root.dataset.pkTheme;const pageContent=content();let markup=`<div class="pk-shell"><header class="pk-header"><div class="pk-wordmark"><span class="pk-brand-emblem" role="img" aria-label="Pokémon">${partyIcon}</span></div><div>${working?'<span class="pk-generation">'+t('AI กำลังบรรยาย…','Narrating…')+'</span>':''}${button(fa('clock-rotate-left'),'nav','data-view="journal" aria-label="'+t('บันทึกการเดินทาง','Field journal')+'"','pk-icon')}${button(fa('window-minimize'),'dock','aria-label="'+t('ย่อไป Chatbar','Move to chatbar')+'"','pk-icon')}${button(fa('xmark'),'close','aria-label="'+t('ปิด','Close')+'"','pk-icon')}</div></header><div class="pk-layout"><nav class="pk-nav" aria-label="Pokémon">${tabs.map(([id,icon,th,en])=>button((id==='team'?partyIcon:fa(icon))+'<span>'+t(th,en)+'</span>'+(id==='team'?'<small>'+game.party.length+'/6</small>':''),'nav','data-view="'+id+'" aria-current="'+(view===id||view==='detail'&&previousView===id?'page':'false')+'"')).join('')}<div class="pk-nav-footer"><span>${game.region.toUpperCase()}</span><small>${game.caught.length} / ${dex.source.species} ${t('จับแล้ว','CAUGHT')}</small></div></nav><main class="pk-main">${root.dataset.pkTheme==='classic-dark'?`<div class="pk-atlas-strip"><span class="pk-atlas-mark" aria-hidden="true"></span><span>${t('แฟ้มการเดินทาง','TRAINER ARCHIVE')}</span><strong>${esc(game.region.toUpperCase())}</strong><span class="pk-atlas-count">${game.party.length} / 6 · ${game.caught.length} ${t('จับแล้ว','CAUGHT')}</span></div>`:''}${notice?'<div class="pk-notice" role="status">'+esc(notice)+'</div>':''}${pageContent}</main></div></div>`;if(root.dataset.pkTheme==='classic-dark')markup=apertureMarkup(pageContent);const route=view+'|'+selectedUid+'|'+selected+'|'+expansion.routeKey()+'|'+release.routeKey();if(markup!==lastMarkup||renderRoute!==route){const focused=root.querySelector(':focus'),name=focused?.name,values=route===renderRoute?[...root.querySelectorAll('input[name],textarea[name],select[name]')].map(n=>[n.name,n.value,n.checked,n.type]):[];root.innerHTML=markup;composeBattleLayout();for(const[key,value,checked,type]of values){const n=root.querySelector('[name="'+CSS.escape(key)+'"]');if(n){if(type==='checkbox')n.checked=checked;else if(n.tagName!=='SELECT'||[...n.options].some(o=>o.value===value))n.value=value;}}if(name&&route===renderRoute)root.querySelector('[name="'+CSS.escape(name)+'"]')?.focus({preventScroll:true});lastMarkup=markup;renderRoute=route;}root.querySelector('.pk-main').scrollTop=scroll;groundObserver.disconnect();for(const node of root.querySelectorAll('.pk-platform'))groundObserver.observe(node);alignGround();renderDock();}
 function renderDock(){
  if(!enabled()||!scope||!dockVisible){dock?.remove('pokemon');return;}
  const lead=game.pokemon[game.battle?.activeUid||game.party[0]],foe=game.battle?.wild;
  const mon=(m,name)=>'<div class="pk-dock-mon">'+image(dex.get(m.key),m)+'<div><strong title="'+esc(name)+'">'+esc(name)+'</strong><small>Lv. '+m.level+'</small>'+hp(m)+'</div></div>';
  panel.innerHTML='<header class="pk-dock-header"><div><span class="pk-brand-emblem" role="img" aria-label="Pokémon">'+partyIcon+'</span><span class="pk-dock-mode">'+(game.battle?t('เทิร์น','Turn')+' '+game.battle.round:t('คู่หูของคุณ','Your companion'))+'</span></div><div>'+button(fa('expand'),'open','aria-label="'+t('เปิดเต็มหน้า','Open full window')+'"','pk-icon')+button(fa('minus'),'minimize','aria-label="'+t('ย่อ','Minimize')+'"','pk-icon')+button(fa('xmark'),'hide-dock','aria-label="'+t('ปิดหน้าต่าง','Close window')+'"','pk-icon')+'</div></header><div class="pk-dock-body">'+
   (!game.started?'<div class="pk-dock-empty"><span>'+t('เลือกเพื่อนร่วมทาง แล้วเริ่มการผจญภัย','Choose a partner and begin your journey.')+'</span>'+button(t('เลือกคู่หู','Choose partner')+' '+fa('arrow-right'),'open','','pk-primary')+'</div>':foe?'<div class="pk-dock-battle">'+mon(lead,monName(lead))+mon(foe,dex.get(foe.key).name)+'</div><div class="pk-moves pk-dock-moves">'+movesMarkup(lead)+'</div><div class="pk-dock-actions">'+button(itemSprite('poke-ball')+'<span>Poké Ball ×'+(game.inventory['poke-ball']||0)+'</span>','catch','data-ball="poke-ball"'+(!game.inventory['poke-ball']||game.battle.trainer?' disabled':''),'pk-quiet')+button(t('เปิดการต่อสู้','Open battle')+' '+fa('arrow-right'),'open','','pk-primary')+'</div>':'<div class="pk-dock-lead">'+mon(lead,monName(lead))+button(fa('compass')+' '+t('สำรวจ','Explore'),'explore','','pk-primary')+'</div><div class="pk-dock-actions">'+button(t('ทีม','Party'),'open','data-view="team"','pk-link')+button('Pokédex','open','data-view="dex"','pk-link')+button(t('บรรยายต่อ','Continue story'),'narrate',!pendingNarration||working?'disabled':'','pk-link')+'</div>')+
   '<div class="pk-dock-result" role="status" aria-live="polite">'+(notice?esc(notice):working?t('AI กำลังบรรยาย…','AI is narrating…'):game.lastResult?logText(game.lastResult):'')+'</div></div>';
  dock?.panel('pokemon',panel,{label:'Pokémon',busy:working});
 }
 function presentNewBattle(previous){if(!previous||!game?.battle||previous.battle?.id===game.battle.id)return false;open('adventure');return root.open;}

 function publishStock(){const stamp=JSON.stringify([scope,enabled(),game?.inventory]);if(stamp===stockStamp)return;stockStamp=stamp;queueMicrotask(()=>{if(!disposed)api.refreshHost?.();});}
 function refresh(){if(disposed)return;const c=context(),next=c.key||'';if(scope!==next||nonce!==c.nonce){motion.cancel();scope=next;nonce=c.nonce;query='';view='adventure';battlePane='commands';nicknameEditing=false;potionPicker=false;notice='';dockVisible=true;pendingNarration=false;cacheStamp='';replayCache.reset();cHost().setExtensionPrompt(ACTION_PROMPT,'',1,0,false,0);if(root.open)root.close();}const active=enabled()&&Boolean(scope);cHost().setExtensionPrompt(PROMPT,'',1,1,false,0);if(!active){motion.cancel();menuSound.stop();cHost().setExtensionPrompt(ACTION_PROMPT,'',1,0,false,0);if(root.open)root.close();dock?.remove('pokemon');publishStock();return;}const previousBattle=game?.battle?.id;const rawGame=replayCache.read(c.chat,rules()),preferences=api.pokemonConfiguration?.()||{};game=Object.keys(preferences).length?{...rawGame,settings:{...rawGame.settings,...preferences}}:rawGame;if(game.battle?.id!==previousBattle)battlePane='commands';pendingNarration=game.pendingNarration;region=game.region;menuSound.configure({volume:game.settings.sound===false?0:game.settings.soundVolume??.32,mix:game.settings.soundMix!==false});cHost().setExtensionPrompt(PROMPT,worldPrompt(game,dex),1,1,false,0);render();publishStock();}
 const cHost=()=>SillyTavern.getContext();
 async function apply(input){if(motion.playing())throw Error(t('รอแอนิเมชันจบก่อน','Wait for the animation to finish'));if(mutating||working||busy())throw Error(t('รอการกระทำก่อนหน้าให้เสร็จ','Wait for the current action to finish'));if(!enabled()||!scope)throw Error(t('เปิด Addon ในแชทนี้ก่อน','Enable this addon in the current chat'));refresh();if(input.type==='settings'&&(input.autoNarrate!==undefined||input.terrain!==undefined)&&api.savePokemonConfiguration){const ticket=context();mutating=true;try{await api.savePokemonConfiguration({...typeof input.autoNarrate==='boolean'?{autoNarrate:input.autoNarrate}:{},...input.terrain!==undefined?{terrain:input.terrain}:{}});assertScope(ticket);}finally{mutating=false;refresh();}return;}const beforeGame=game;const c=cHost(),ticket=context(),rows=c.chat,message=rows.filter(m=>!m.is_user&&!m.is_system).at(-1);if(!message)throw Error('Start the chat first');const imported=input.type==='import-item',beforeState=context().state;let nextState;if(imported){const legacy=beforeState.inventory?.find(i=>i.id===input.sourceId),known=resolveRoleItem(dex,legacy);if(!legacy||legacy.quantity<=0||legacy.commerceRightId||known?.id!==input.item)throw Error('This inventory item cannot be imported');nextState=structuredClone(beforeState);nextState.inventory=nextState.inventory.filter(i=>i.id!==legacy.id);input={type:'grant-item',source:'import',item:known.id,quantity:legacy.quantity,sourceId:legacy.id};}const event=journalEvent({...input,engine:3,context:{place:context().state?.location?.place||'',time:context().state?.worldClock?.time||'',weather:context().state?.weather||context().state?.worldClock?.weather||''},id:newActionId()},message);transition(game,event,dex,rules());const previous=message.extra,extra={...previous,[JOURNAL]:[...previous?.[JOURNAL]||[],event]};assertScope(ticket);mutating=true;message.extra=extra;try{if(imported){const saved=await api.commitState(nextState,'pokemon-inventory',{saveMetadataOverride:savePokemonChat});if(!saved)throw Error('Inventory import was not saved');}else await savePokemonChat(c);assertScope(ticket);pendingNarration=true;cacheStamp='';notice='';refresh();}catch(error){if(message.extra===extra)message.extra=previous;cacheStamp='';refresh();throw error;}finally{mutating=false;}api.refreshHost?.();presentNewBattle(beforeGame);playMotion(motionSequence(beforeGame,game,event),beforeGame.battle?beforeGame:game);if(game.settings.autoNarrate&&!['settings','narrated'].includes(input.type))void narrate().catch(showError);return event;}
 function assertScope(ticket){const c=context();if(!enabled()||c.key!==ticket.key||c.nonce!==ticket.nonce)throw Error(t('เปลี่ยนแชทระหว่างบันทึก','Chat changed during the action'));}
 const errorThai={'Pokémon progress could not be saved. Check the connection and retry.':'บันทึก Pokémon ไม่สำเร็จ ตรวจการเชื่อมต่อแล้วลองใหม่','Chat integrity check failed. Reload before retrying; no overwrite was requested.':'ตรวจสอบไฟล์แชทไม่ผ่าน โหลดหน้าใหม่ก่อนลองอีกครั้ง ระบบไม่ได้เขียนทับไฟล์','This item would have no effect; nothing was consumed':'ไอเทมนี้ไม่มีผลกับเป้าหมาย จึงไม่หักจำนวน','Visit a Pokémon Center in the story first':'ไปถึง Pokémon Center ในโรลก่อนรับบริการ','Visit this Gym in the story first':'ไปถึงยิมนี้ในโรลก่อนท้าสู้','The compatible TM is not in your bag':'ยังไม่มี TM ที่ตรงกับท่านี้ในกระเป๋า','This Pokémon cannot learn that move here':'โปเกมอนตัวนี้ยังเรียนท่านี้ไม่ได้','Finish the battle before changing moves':'จบการต่อสู้ก่อนเปลี่ยนท่า','Visit a Move Tutor or Pokémon Center':'ไปพบผู้ฝึกท่าหรือ Pokémon Center ก่อน','Enable Sandbox yourself before using cheats':'เปิด Sandbox ด้วยตัวเองก่อนใช้คำสั่งโกง','Finish the encounter before editing the world':'จบการต่อสู้ก่อนแก้ไขข้อมูล','IV must be an integer from 0 to 31':'IV ต้องเป็นจำนวนเต็ม 0–31','EV must be 0–252 per stat and at most 510 total':'EV ต้องอยู่ที่ 0–252 ต่อค่า และรวมไม่เกิน 510','Only wild Pokémon can be caught':'จับได้เฉพาะโปเกมอนป่าเท่านั้น','A fainted Pokémon needs Revive or a Pokémon Center':'ตัวที่หมดสภาพต้องใช้ Revive หรือรักษาที่ Pokémon Center','Choose a fainted Pokémon':'เลือกตัวที่หมดสภาพก่อน','Leave the Center or Gym before exploring for wild Pokémon':'ออกจากศูนย์หรือยิมก่อนสำรวจหาโปเกมอนป่า','Choose a supported permanent form; battle transformations are not simulated':'เลือกฟอร์มถาวรที่รองรับ การแปลงร่างระหว่างสู้ยังไม่จำลอง','Accept the quest and reach its destination first':'รับภารกิจและไปถึงจุดหมายก่อน','This rare encounter has already been completed':'ภารกิจพบตัวนี้สำเร็จไปแล้ว','Stat overrides must be 1–99999 or blank':'ค่าสเตตัสกำหนดเองต้องเป็น 1–99999 หรือเว้นว่าง'};
 function showError(error){const message=String(error.message||error);notice=t(errorThai[message]||message,message);render();}
 async function narrate(){if(working||busy())throw Error(t('AI กำลังตอบอยู่','AI is already generating'));assertScope(context());refresh();const c=cHost(),ticket=context(),rows=c.chat,last=rows.at(-1),beforeText=String(last?.mes||'');let completed=false;if(!last||last.is_user||last.is_system)throw Error(t('รอให้ AI ตอบก่อน แล้วกดบรรยายต่อ','Wait for an assistant reply before continuing'));const restoreDraft=preserveDraft(document,context);working=true;render();const clear=()=>c.setExtensionPrompt(ACTION_PROMPT,'',1,0,false,0);const changed=()=>clear();c.eventSource.on(c.eventTypes.CHAT_CHANGED,changed);c.setExtensionPrompt(ACTION_PROMPT,'Continue this assistant message from the resolved Pokémon events. '+JSON.stringify(game.logs.slice(-6))+' Narrate the consequences; do not speak for the player and do not repeat the mechanical action or add rewards. Leave the next choice to the player.',1,0,false,0);try{await c.generate('continue',{automatic_trigger:true,depth:1});if(context().key===ticket.key&&context().nonce===ticket.nonce&&String(last.mes||'')!==beforeText)completed=true;}finally{restoreDraft();clear();c.eventSource.removeListener(c.eventTypes.CHAT_CHANGED,changed);working=false;cacheStamp='';refresh();}if(completed)await apply({type:'narrated'});else throw Error(t('AI ยังไม่ส่งคำตอบ ตรวจการเชื่อมต่อแล้วลองบรรยายอีกครั้ง ผลการเล่นยังถูกเก็บไว้','No AI response received. Check the connection and retry; your progress is saved.'));}
 async function handle(b){if(await release.handle(b)||await expansion.handle(b))return;const action=b.dataset.pkAction;if(['close','dock','hide-dock','minimize','open','nav'].includes(action)){if(action==='close'){root.close();return;}if(action==='hide-dock'){dockVisible=false;dock?.remove('pokemon');return;}if(action==='minimize'){dock?.minimize('pokemon');return;}if(action==='dock'){dockVisible=true;renderDock();dock?.select('pokemon');root.close();return;}if(action==='nav'){view=b.dataset.view;notice='';selectedUid='';render();root.querySelector('.pk-main').scrollTop=0;return;}open(b.dataset.view||'adventure');return;}
  if(action==='battle-menu'){battlePane=b.dataset.pane;render();return;}
  if(action==='dex-filters'){dexFilters=!dexFilters;render();return;}
  if(action==='dex-mode'){showForms=b.dataset.forms==='true';dexPage=0;render();return;}
  if(action==='filter-generation'){generation=Number(b.dataset.generation);dexPage=0;render();return;}
  if(action==='clear-filters'){type='';generation=0;dexPage=0;render();return;}
  if(action==='edit-nickname'){nicknameEditing=!nicknameEditing;render();root.querySelector('[name=nickname]')?.focus();return;}
  if(action==='potion-picker'){potionPicker=!potionPicker;render();root.querySelector('.pk-potion-picker')?.scrollIntoView({block:'nearest'});return;}
  if(action==='starter-region'){region=b.dataset.region;render();return;}
  if(action==='choose-starter'){await apply({type:'starter',speciesId:Number(b.dataset.species),region});view='adventure';render();return;}
  if(action==='dex-detail'||action==='mon-detail'){if(view!=='detail')previousView=view;selectedUid=action==='mon-detail'?b.dataset.uid:'';nicknameEditing=false;selected=selectedUid?game.pokemon[selectedUid].key:b.dataset.key;view='detail';render();root.querySelector('.pk-main').scrollTop=0;return;}
  if(action==='filter-type'){type=b.dataset.type;dexPage=0;render();return;}if(action==='toggle-forms'){showForms=!showForms;dexPage=0;render();return;}if(action==='dex-page'){dexPage=Number(b.dataset.page);render();root.querySelector('.pk-main').scrollTop=0;return;}
  if(action==='choose-medicine'){medicine=b.dataset.item;view=game.battle?'battle-medicine':'bag';render();return;}if(action==='bag-catalogue'){bagCatalogue=!bagCatalogue;bagPage=0;render();return;}if(action==='bag-page'){bagPage=Math.max(0,bagPage+Number(b.dataset.step));render();return;}
  if(action==='theme-set'||action==='sound-toggle'||action==='sound-mix-toggle'||action==='dex-image-set'){if(mutating||working||busy())return;const ticket=context();mutating=true;try{await api.savePokemonConfiguration(action==='theme-set'?{theme:b.dataset.theme}:action==='dex-image-set'?{dexImageMode:b.dataset.mode}:action==='sound-mix-toggle'?{soundMix:game.settings.soundMix===false}:{sound:game.settings.sound===false});assertScope(ticket);}finally{mutating=false;refresh();}return;}if(action==='narrate'){await narrate();return;}if(action==='motion-toggle'){if(mutating||working||busy())return;const ticket=context(),value=game.settings.motion===false;mutating=true;render();try{await api.savePokemonConfiguration({motion:value});assertScope(ticket);}finally{mutating=false;refresh();}return;}if(action==='auto-narrate'){await apply({type:'settings',autoNarrate:!game.settings.autoNarrate});return;}if(action==='set-region'){await apply({type:'settings',region:b.dataset.region});return;}
  const event={type:action};if(b.dataset.uid)event.uid=b.dataset.uid;if(b.dataset.move)event.moveId=Number(b.dataset.move);if(b.dataset.ball)event.ball=b.dataset.ball;if(b.dataset.to)event.to=Number(b.dataset.to);await apply(event);if(['attack','potion','catch','switch','run'].includes(action))battlePane='commands';if(action==='switch')view='adventure';if(action==='potion')potionPicker=false;if(['evolve','trade-evolve'].includes(action)&&selectedUid)selected=game.pokemon[selectedUid].key;render();
 }
 root.addEventListener('submit',e=>{if(release.submit(e))return;if(e.target.matches('[data-pk-use-item]')){e.preventDefault();const f=new FormData(e.target);void apply({type:'use-item',item:medicine,uid:f.get('uid'),moveId:Number(f.get('moveId'))}).then(()=>{medicine='';battlePane='commands';view=game.battle?'adventure':'bag';render();}).catch(showError);return;}try{if(expansion.submit(e))return;}catch(error){showError(error);return;}if(!e.target.matches('[data-pk-nickname]'))return;e.preventDefault();const name=new FormData(e.target).get('nickname');void apply({type:'nickname',uid:selectedUid,name}).then(()=>{nicknameEditing=false;render();}).catch(showError);});
 const menuSound=createPokemonMenuSound({url:new URL('assets/menu-confirm-v2.wav',import.meta.url).href});const clicked=e=>{const b=e.target.closest('[data-pk-action]');if(b&&!b.disabled&&!motion.playing()){if(game?.settings.sound!==false){if(b.dataset.pkAction==='sound-mix-toggle'&&game.settings.soundMix===false)menuSound.configure({mix:true});menuSound.play();}void handle(b).catch(showError);}};function artError(e){const img=e.target;if(!img.matches?.('img:not(.pk-battle-sprite)')||img.dataset.failed)return;
  if(img.matches('.pk-pokemon-sprite')){failedSprites.add(img.src);const p=dex.get(img.dataset.pkArtKey),m={shiny:img.dataset.pkShiny==='1',traits:{gender:img.dataset.pkGender}},next=portraitSprites(p,m)[0];if(next){img.dataset.pkAnimated=String(next.animated);img.classList.toggle('pk-sprite-idle',spriteMotion()&&!next.animated);img.src=next.url;return;}const artwork=imageUrl(p,m);if(artwork&&artwork!==img.src&&!failedSprites.has(artwork)){img.classList.remove('pk-pokemon-sprite','pk-sprite-idle');img.dataset.pkArtFallback='true';img.src=artwork;return;}}
  else if(img.dataset.pkArtKey&&!img.dataset.pkArtFallback){const url=frontStill(dex.get(img.dataset.pkArtKey),{shiny:img.dataset.pkShiny==='1',traits:{gender:img.dataset.pkGender}});if(url&&url!==img.src){img.dataset.pkArtFallback='true';img.src=url;return;}}
  img.dataset.failed='true';const fallback=document.createElement('span');fallback.className='pk-art-missing';fallback.setAttribute('role','img');fallback.setAttribute('aria-label',img.alt||t('ภาพไม่พร้อมใช้งาน','Artwork unavailable'));fallback.innerHTML=fa('paw');img.replaceWith(fallback);
 }root.addEventListener('error',artError,true);panel.addEventListener('error',artError,true);root.addEventListener('click',clicked);panel.addEventListener('click',clicked);
 root.addEventListener('input',e=>{if(e.target.matches('[data-pk-volume]')){const value=Math.max(0,Math.min(100,Number(e.target.value)));e.target.style.setProperty('--pk-volume',value+'%');e.target.nextElementSibling.value=value+'%';menuSound.configure({volume:game.settings.sound===false?0:value/100});return;}if(expansion.input(e))return;if(e.target.matches('[data-pk-bag-search]')){bagSearch=e.target.value;bagPage=0;const caret=e.target.selectionStart;render();const n=root.querySelector('[data-pk-bag-search]');n?.focus({preventScroll:true});n?.setSelectionRange(caret,caret);return;}if(e.target.matches('[data-pk-search]')){query=e.target.value;dexPage=0;const caret=e.target.selectionStart;render();const input=root.querySelector('[data-pk-search]');input?.focus({preventScroll:true});try{input.setSelectionRange(caret,caret);}catch{}}});

 for(const node of [root,panel])for(const event of ['touchstart','touchmove','pointerdown','pointermove'])node.addEventListener(event,e=>e.stopPropagation(),{passive:true});
 const subscriptions=[],host=cHost();for(const event of [...new Set([host.eventTypes.CHAT_CHANGED,host.eventTypes.MESSAGE_SENT,host.eventTypes.USER_MESSAGE_RENDERED,host.eventTypes.MESSAGE_RECEIVED,host.eventTypes.MESSAGE_UPDATED,host.eventTypes.MESSAGE_EDITED,host.eventTypes.MESSAGE_SWIPED,host.eventTypes.MESSAGE_DELETED].filter(Boolean))]){const fn=()=>{const before=game,oldScope=scope,oldNonce=nonce;if(event!==host.eventTypes.MESSAGE_RECEIVED)motion.cancel();refresh();if(event===host.eventTypes.MESSAGE_RECEIVED&&!mutating&&oldScope===scope&&oldNonce===nonce&&before&&!before.battle&&game?.battle){presentNewBattle(before);playMotion(motionSequence(before,game,{type:'story-encounter'}),game);}};host.eventSource.on(event,fn);subscriptions.push([event,fn]);}
 const language=e=>{if(e.target?.id==='tretaresia-rpg-language')render();};document.addEventListener('change',language);window.addEventListener('resize',viewport);visualViewport?.addEventListener('resize',viewport);viewport();
 function open(next='adventure'){refresh();if(!enabled()||!scope)return;view=next;notice='';render();viewport();if(!root.open)root.showModal();root.querySelector('.pk-main').scrollTop=0;}
 root.addEventListener('change',event=>{if(event.target.matches('[data-pk-volume]')){const value=Number(event.target.value)/100,ticket=context();if(mutating||working||busy()){refresh();return;}mutating=true;render();let committed=false;void api.savePokemonConfiguration({soundVolume:value}).then(()=>{assertScope(ticket);committed=true;}).catch(showError).finally(()=>{mutating=false;refresh();if(committed&&!disposed&&enabled()&&context().key===ticket.key&&context().nonce===ticket.nonce&&game?.settings.sound!==false)menuSound.play();});return;}if(event.target.matches('[data-pk-medicine-target]')){medicineTarget=event.target.value;render();return;}if(event.target.matches('[data-pk-terrain]'))void apply({type:'settings',terrain:event.target.value}).catch(showError);});
 const app={root,panel,open,refresh,inventory:()=>enabled()&&scope&&game&&scopeKey()===scope&&context().nonce===nonce?bridgeEntries(game,dex):[],filterInventoryOps:(ops,source)=>enabled()?filterInventoryOps(ops,narratedEncounters(source,dex),dex):ops,world:()=>{refresh();return enabled()&&scope?copyGame():null;},debug:()=>({replay:replayCache.stats(),storyRejected:(context().chat||[]).slice(-3).flatMap(m=>m.is_user?[]:parsePokemonStory(m.mes,dex).rejected),enabled:enabled(),view,scope,working,mutating,source:dex.source,party:game?.party?.length,selected,notice}),prepareGeneration(){refresh();},destroy(){disposed=true;for(const [event,fn]of subscriptions)host.eventSource.removeListener(event,fn);document.removeEventListener('change',language);window.removeEventListener('resize',viewport);visualViewport?.removeEventListener('resize',viewport);host.setExtensionPrompt(PROMPT,'',1,1,false,0);host.setExtensionPrompt(ACTION_PROMPT,'',1,0,false,0);dock?.remove('pokemon');motion.destroy();menuSound.destroy();groundObserver.disconnect();groundAnchors.clear();failedSprites.clear();root.removeEventListener('error',spriteError,true);root.removeEventListener('error',artError,true);panel.removeEventListener('error',artError,true);reducedMotion.removeEventListener('change',reducedChanged);root.remove();style.remove();if(globalThis.RoleForgePokemon===app)delete globalThis.RoleForgePokemon;}};
